<?php
require_once __DIR__.'/../includes/helpers.php'; require_role('admin'); $title=t('nav.admin_assessments');
if($_SERVER['REQUEST_METHOD']==='POST'){
  verify_csrf(); $id=(int)($_POST['assessment_id']??0); $action=$_POST['action']??''; $a=fetch_one('SELECT * FROM ae_field_assessments WHERE id=?',[$id]);
  if($a){
    if($action==='approve'){ query("UPDATE ae_field_assessments SET status='approved',reviewed_by=?,reviewed_at=NOW() WHERE id=?",[current_user()['id'],$id]); query('UPDATE ae_heritage_sites SET risk_percentage=?,risk_level=? WHERE id=?',[$a['risk_percentage'],$a['risk_level'],$a['site_id']]); if($a['report_id']) query("UPDATE ae_incident_reports SET status='closed' WHERE id=?",[$a['report_id']]); flash('success',localized('تم اعتماد التقييم وتحديث الموقع.','Assessment approved and site risk updated.')); }
    elseif($action==='return'){ query("UPDATE ae_field_assessments SET status='returned',reviewed_by=?,reviewed_at=NOW() WHERE id=?",[current_user()['id'],$id]); flash('warning',localized('تمت إعادة التقييم للتعديل.','Assessment returned for revision.')); }
    elseif($action==='reject'){ query("UPDATE ae_field_assessments SET status='rejected',reviewed_by=?,reviewed_at=NOW() WHERE id=?",[current_user()['id'],$id]); flash('danger',localized('تم رفض التقييم.','Assessment rejected.')); }
  }
  redirect('admin/assessments.php');
}
$rows=fetch_all('SELECT fa.*,s.name site_name,s.city,u.name archaeologist FROM ae_field_assessments fa JOIN ae_heritage_sites s ON s.id=fa.site_id JOIN ae_users u ON u.id=fa.archaeologist_id ORDER BY FIELD(fa.status,"submitted","returned","approved","rejected"),fa.id DESC'); include __DIR__.'/../includes/header.php';
?>
<section class="page-hero"><span class="eyebrow"><?= h(localized('اعتماد رسمي','Official Approval')) ?></span><h1><?= h(t('nav.admin_assessments')) ?></h1><p><?= h(localized('راجع نتيجة الزيارة والمعايير والتوصيات قبل اعتماد التقرير وتحديث الخريطة.','Review visit results, criteria, and recommendations before publishing the report and updating the map.')) ?></p></section>
<div class="table-card"><div class="table-responsive"><table class="table"><thead><tr><th><?= h(t('reports.site')) ?></th><th><?= h(t('reports.archaeologist')) ?></th><th><?= h(localized('نوع الخطر','Risk Type')) ?></th><th><?= h(t('reports.risk')) ?></th><th><?= h(t('reports.recommendations')) ?></th><th><?= h(t('common.status')) ?></th><th><?= h(t('common.actions')) ?></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><b><?= h($r['site_name']) ?></b><br><span class="mini"><?= h($r['city']) ?> — <?= h($r['visit_date']) ?></span></td><td><?= h($r['archaeologist']) ?></td><td><?= h($r['risk_type']) ?></td><td><span class="badge badge-<?= h(risk_class($r['risk_percentage'])) ?>"><?= h(risk_label($r['risk_level'])) ?> — <?= (int)$r['risk_percentage'] ?>%</span></td><td><?= h(excerpt($r['recommendations'],110)) ?></td><td><span class="badge badge-neutral"><?= h(status_label($r['status'])) ?></span></td><td><?php if($r['status']==='submitted'): ?><form method="post" class="actions"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><input type="hidden" name="assessment_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-primary" name="action" value="approve"><i class="ti ti-check"></i><?= h(localized('اعتماد','Approve')) ?></button><button class="btn btn-light" name="action" value="return"><i class="ti ti-arrow-back-up"></i><?= h(localized('إعادة','Return')) ?></button><button class="btn btn-danger" name="action" value="reject"><i class="ti ti-x"></i><?= h(localized('رفض','Reject')) ?></button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty"><?= h(localized('لا توجد تقييمات حتى الآن.','No assessments are available yet.')) ?></td></tr><?php endif; ?></tbody></table></div></div>
<?php include __DIR__.'/../includes/footer.php'; ?>
